def divisible_by_digits(startnum, endnum):
    result = []
    for num in range(startnum, endnum + 1):
        digits_str = str(num)
        is_divisible = True
        if len(digits_str) == 0:
            continue

        # Convert each digit to integer and check divisibility
        try:
            for char_digit in digits_str:
                digit = int(char_digit)
                if num % digit != 0:
                    is_divisible = False
                    break
        except ValueError:
            is_divisible = False

        if is_divisible:
            result.append(num)
    return result

